## auth-controller.ts
```ts
import { Request, Response } from "express";
import { registerUser } from "../services/auth-service";
import { registerSchema } from "../validations/auth-validation";

export const register = async (req: Request, res: Response) => {
  try {
    // validasi input
    const { error, value } = registerSchema.validate(req.body);
    if (error) {
      return res
        .status(400)
        .json({
          code: 400,
          status: "error",
          message: "Validation error",
          errors: error.details[0]?.message,
        });
    }

    const { name, phone, email, password } = value;
    const user = await registerUser(name, phone, email, password);

    return res.status(201).json({
      code: 201,
      status: "success",
      message: "User registered successfully",
      data: {
        id: user.name,
        phone: user.phone,
        email: user.email,
        password: user.password,
      },
    });
  } catch (err) {
    console.error(err);
    return res
      .status(500)
      .json({ code: 500, status: "error", message: "Internal server error" });
  }
};
```
## auth-validation.ts
```ts
import Joi from "joi";

export const registerSchema = Joi.object({
  name: Joi.string().min(3).max(100).required(),
  phone: Joi.string()
    .pattern(/^(?:\+62|62|0)[0-9]{9,13}$/)
    .message("Phone number must be a valid Indonesian number")
    .required(),
  email: Joi.string().email().required(),
  password: Joi.string().min(6).required(),
});
```
## auth-services.ts
```ts
import bcrypt from "bcrypt";
import prisma from "../prisma/client";

export async function registerUser(
  name: string,
  phone: string | null,
  email: string,
  password: string
) {
  // manual validation (mirip logic Joi)
  if (!name || name.length < 3 || name.length > 100) {
    throw new Error("Name must be between 3 and 100 characters");
  }

  const phoneRegex = /^(?:\+62|62|0)[0-9]{9,13}$/;
  if (phone && !phoneRegex.test(phone)) {
    throw new Error("Phone number must be a valid Indonesian number");
  }

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    throw new Error("Invalid email format");
  }

  if (!password || password.length < 6) {
    throw new Error("Password must be at least 6 characters");
  }

  // hash password
  const hashedPassword = await bcrypt.hash(password, 10);

  // simpan ke database
  const user = await prisma.user.create({
    data: {
      name,
      phone,
      email,
      password: hashedPassword,
    },
  });

  return user;
}
```
